import React from "react";

const About = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "80px 20px",
        fontFamily: "Poppins, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "#fff1f8",
        backgroundImage: `
          radial-gradient(#ffd6ec 2px, transparent 2px),
          radial-gradient(#c9f3ff 2px, transparent 2px)
        `,
        backgroundSize: "60px 60px",
        backgroundPosition: "0 0, 30px 30px",
      }}
    >
      <div
        style={{
          maxWidth: "900px",
          background: "white",
          padding: "60px 50px",
          borderRadius: "35px",
          boxShadow: "0 25px 60px rgba(0,0,0,0.12)",
          textAlign: "center",
        }}
      >
        <h1
          style={{
            fontSize: "42px",
            color: "#d63384",
            marginBottom: "30px",
            fontWeight: "700",
          }}
        >
          🌸 About Us
        </h1>

        <p
          style={{
            fontSize: "19px",
            lineHeight: "1.9",
            color: "#444",
            marginBottom: "25px",
          }}
        >
          <strong>Nanhe Farishte – Kiran Knits</strong> ek brand nahi,
          ek maa ke dil se nikli hui kahani hai. Iski shuruaat hui ek maa ke
          pyaar se, jo apne nanhe farishte ke liye har sardi mein apne
          haathon se garam sweaters, caps aur socks bunna pasand karti thi.
        </p>

        <p
          style={{
            fontSize: "19px",
            lineHeight: "1.9",
            color: "#555",
            marginBottom: "25px",
          }}
        >
          Har dhage mein sirf wool nahi, balki mamta, dua aur suraksha ki
          garmahat basi hoti hai. Yahan har sweater sirf kapda nahi —
          ek ehsaas hai, aur har bunai ek dua hai jo bachchon ki
          muskurahat ke liye ki jaati hai.
        </p>

        <p
          style={{
            fontSize: "19px",
            lineHeight: "1.9",
            color: "#666",
            marginBottom: "40px",
          }}
        >
          Hum maante hain ki bachpan sabse komal aur khoobsurat daur hota hai.
          Is bachpan ko pyaar aur sukoon ki garmahat dena hi hamara sapna hai.
        </p>

        <div
          style={{
            marginTop: "20px",
            paddingTop: "20px",
            borderTop: "2px dashed #ffd6ec",
          }}
        >
          <p
            style={{
              fontSize: "18px",
              color: "#d63384",
              fontWeight: "600",
              marginBottom: "8px",
            }}
          >
            Made with ❤️
          </p>

          <p
            style={{
              fontSize: "20px",
              color: "#6f42c1",
              fontWeight: "700",
            }}
          >
            By Kiran Tiwari
          </p>
        </div>
      </div>
    </div>
  );
};

export default About;
